// TestFramesFixture cross-checks the Go implementation against the frame fixture
// generated by the TypeScript implementation (test/interop/crh_frames.json). Every
// positive is decoded, compared with an independently hand-written expected value
// derived from doc/protocol.md and the entry's description, then re-encoded and
// compared with the fixture hex. Every negative must be rejected by the same decode
// path (frame and body).
func TestFramesFixture(t *testing.T) {
	path := filepath.Join("..", "..", "..", "test", "interop", "crh_frames.json")
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	var fixture struct {
		Positive []struct {
			ID          string `json:"id"`
			Description string `json:"description"`
			Hex         string `json:"hex"`
		} `json:"positive"`
		Negative []struct {
			ID          string `json:"id"`
			Description string `json:"description"`
			Hex         string `json:"hex"`
		} `json:"negative"`
	}
	if err := json.Unmarshal(data, &fixture); err != nil {
		t.Fatalf("parse %s: %v", path, err)
	}

	// The reverse direction: every hand-written expectation must also appear in the fixture,
	// so an entry that disappears cannot silently shrink the coverage.
	positive := make(map[string]bool, len(fixture.Positive))
	for _, entry := range fixture.Positive {
		positive[entry.ID] = true
	}
	for _, id := range fixtureExpectedIDs {
		if !positive[id] {
			t.Errorf("hand-written expectation %s is missing from %s", id, path)
		}
	}

	for _, entry := range fixture.Positive {
		t.Run(entry.ID, func(t *testing.T) {
			raw := mustHex(t, entry.Hex)
			got, err := decodeFixtureValue(raw, entry.ID)
			if err != nil {
				t.Fatalf("decode: %v", err)
			}
			want, ok := expectedFixtureValue(entry.ID)
			if !ok {
				t.Fatalf("no hand-written expectation for %s", entry.ID)
			}
			if !reflect.DeepEqual(got, want) {
				t.Fatalf("decoded value mismatch:\n got %#v\nwant %#v", got, want)
			}
			encoded, err := encodeFixtureValue(got)
			if err != nil {
				t.Fatalf("re-encode: %v", err)
			}
			if got := hex.EncodeToString(encoded); got != entry.Hex {
				t.Fatalf("re-encoded as %s, want %s", got, entry.Hex)
			}
		})
	}

	for _, entry := range fixture.Negative {
		t.Run(entry.ID, func(t *testing.T) {
			if _, err := decodeFixtureValue(mustHex(t, entry.Hex), entry.ID); err == nil {
				t.Fatalf("accepted: %s", entry.Description)
			}
		})
	}
}

// fixtureFrame is a decoded frame plus its schema-typed body. Error responses carry Err
// instead of Body.
type fixtureFrame struct {
	Kind FrameKind
	ID   Uint
	Name string
	OK   bool
	Err  *Error
	Body any
}

func decodeFixtureValue(raw []byte, id string) (any, error) {
	switch {
	case strings.HasPrefix(id, "handshake.init."):
		var init HandshakeInit
		if err := Unmarshal(raw, &init); err != nil {
			return nil, err
		}
		return init, nil
	case strings.HasPrefix(id, "handshake.response."):
		var response HandshakeResponse
		if err := Unmarshal(raw, &response); err != nil {
			return nil, err
		}
		return response, nil
	}

	frame, err := DecodeFrame(raw)
	if err != nil {
		return nil, err
	}
	decoded := fixtureFrame{
		Kind: frame.Kind,
		ID:   frame.ID,
		Name: frame.Name,
		OK:   frame.OK,
		Err:  frame.Err,
	}
	if frame.Kind == FrameResponse && !frame.OK {
		return decoded, nil
	}
	body, err := decodeFixtureBody(frame)
	if err != nil {
		return nil, err
	}
	decoded.Body = body
	return decoded, nil
}

func decodeFixtureBody(frame *Frame) (any, error) {
	switch frame.Kind {
	case FrameRequest:
		switch frame.Name {
		case CmdHello:
			var v Hello
			return v, Unmarshal(frame.Body, &v)
		case CmdPing:
			var v Ping
			return v, Unmarshal(frame.Body, &v)
		case CmdTaskStart:
			var v TaskStart
			return v, Unmarshal(frame.Body, &v)
		case CmdTaskInput:
			var v TaskInput
			return v, Unmarshal(frame.Body, &v)
		case CmdTaskCancel:
			var v TaskCancel
			return v, Unmarshal(frame.Body, &v)
		case CmdTaskQuery:
			var v TaskQuery
			return v, Unmarshal(frame.Body, &v)
		}
	case FrameResponse:
		switch frame.Name {
		case CmdHello:
			var v Welcome
			return v, Unmarshal(frame.Body, &v)
		case CmdPing:
			var v Ping
			return v, Unmarshal(frame.Body, &v)
		case CmdTaskStart, CmdTaskInput, CmdTaskCancel:
			var v Empty
			return v, Unmarshal(frame.Body, &v)
		case CmdTaskQuery:
			var v TaskStatus
			return v, Unmarshal(frame.Body, &v)
		}
	case FrameEvent:
		switch frame.Name {
		case EventTaskOutput:
			var v TaskOutput
			return v, Unmarshal(frame.Body, &v)
		case EventTaskExit:
			var v TaskExit
			return v, Unmarshal(frame.Body, &v)
		case EventFacts:
			var v Facts
			return v, Unmarshal(frame.Body, &v)
		case EventNodeStatus:
			var v NodeStatus
			return v, Unmarshal(frame.Body, &v)
		case EventOutputAck:
			var v OutputAck
			return v, Unmarshal(frame.Body, &v)
		case EventTaskExitAck:
			var v TaskExitAck
			return v, Unmarshal(frame.Body, &v)
		}
	}
	return nil, fmt.Errorf("no body type for frame kind %d name %q", frame.Kind, frame.Name)
}

func encodeFixtureValue(value any) ([]byte, error) {
	switch v := value.(type) {
	case HandshakeInit:
		return Marshal(v)
	case HandshakeResponse:
		return Marshal(v)
	case fixtureFrame:
		switch {
		case v.Kind == FrameRequest:
			return EncodeRequest(v.ID, v.Name, v.Body)
		case v.Kind == FrameResponse && v.OK:
			return EncodeResponse(v.ID, v.Name, v.Body)
		case v.Kind == FrameResponse:
			if v.Err == nil {
				return nil, fmt.Errorf("fixture %d: error response without Error", v.ID)
			}
			return EncodeErrorResponse(v.ID, v.Name, v.Err.Code, v.Err.Message)
		case v.Kind == FrameEvent:
			return EncodeEvent(v.Name, v.Body)
		}
	}
	return nil, fmt.Errorf("cannot encode fixture value %T", value)
}

// The hand-written expectations below are transcribed from doc/protocol.md and the
// description of each fixture entry, independently of the TypeScript generator.

func fixtureCommands() []string {
	return []string{
		CmdHello, CmdPing, CmdTaskStart, CmdTaskInput, CmdTaskCancel, CmdTaskQuery,
		EventTaskOutput, EventTaskExit, EventFacts, EventNodeStatus, EventOutputAck, EventTaskExitAck,
	}
}

func fixtureFacts() Facts {
	return Facts{
		Hostname:        "node-1",
		OSID:            "ubuntu",
		OSVersionID:     "24.04",
		OSPrettyName:    "Ubuntu 24.04 LTS",
		Kernel:          "6.8.0-31-generic",
		Arch:            "x86_64",
		InitSystem:      "systemd",
		PackageManagers: []string{"apt", "snap"},
		PrivilegeTools:  []string{"sudo"},
		NotesPath:       "/etc/crh/notes",
		Groups:          []string{"sudo", "docker"},
		ClockOffsetMS:   -1234,
	}
}

func fixtureHash(value byte) Hash {
	var h Hash
	for i := range h {
		h[i] = value
	}
	return h
}

// fixtureExpectedIDs lists the entries expectedFixtureValue has a hand-written value for;
// TestFramesFixture checks that the fixture still contains every one of them.
var fixtureExpectedIDs = []string{
	"handshake.init.no-enroll",
	"handshake.init.enroll",
	"handshake.response.active",
	"handshake.response.pending",
	"request.hello",
	"response.hello",
	"request.ping",
	"response.ping",
	"request.task.start.exec.argv",
	"request.task.start.exec.shell",
	"request.task.start.file.read",
	"request.task.start.file.write",
	"request.task.start.file.edit",
	"request.task.start.file.stat",
	"request.task.start.file.list",
	"response.task.start",
	"request.task.input",
	"response.task.input",
	"request.task.cancel",
	"response.task.cancel",
	"request.task.query",
	"response.task.query",
	"response.error",
	"event.task.output",
	"event.task.exit.code",
	"event.task.exit.signal",
	"event.task.exit.error",
	"event.facts",
	"event.node.status",
	"event.task.output.ack",
	"event.task.exit.ack",
}

func expectedFixtureValue(id string) (any, bool) {
	switch id {
	case "handshake.init.no-enroll":
		return HandshakeInit{
			ProtocolMajor: 1,
			ProtocolMinor: 0,
			Commands:      fixtureCommands(),
			CRHAVersion:   "0.1.0-test",
			ClientTimeMS:  1700000000000,
			Enroll:        nil,
		}, true
	case "handshake.init.enroll":
		return HandshakeInit{
			ProtocolMajor: 1,
			ProtocolMinor: 0,
			Commands:      []string{CmdHello, CmdPing},
			CRHAVersion:   "0.1.0-test",
			ClientTimeMS:  1700000000000,
			Enroll: &Enrollment{
				TokenSecret: "enroll-secret",
				Hostname:    "node-1",
				Facts:       fixtureFacts(),
			},
		}, true
	case "handshake.response.active":
		return HandshakeResponse{
			ProtocolMajor: 1,
			ProtocolMinor: 0,
			Commands:      fixtureCommands(),
			ConnectionID:  "conn-1",
			ServerTimeMS:  1700000001234,
			NodeState:     NodeActive,
			NodeID:        "node-1",
		}, true
	case "handshake.response.pending":
		return HandshakeResponse{
			ProtocolMajor: 1,
			ProtocolMinor: 0,
			Commands:      fixtureCommands(),
			ConnectionID:  "conn-1",
			ServerTimeMS:  1700000001234,
			NodeState:     NodePending,
			NodeID:        "node-1",
		}, true

	case "request.hello":
		return fixtureFrame{
			Kind: FrameRequest, ID: 1, Name: CmdHello,
			Body: Hello{
				Tasks: []TaskStatus{
					{TaskID: "t-run", State: TaskRunning, StdoutEnd: 10, StderrEnd: 2},
				},
				TaskKinds:      []string{"exec", "file.read"},
				PrivilegedMode: "disabled",
			},
		}, true
	case "response.hello":
		return fixtureFrame{
			Kind: FrameResponse, ID: 1, Name: CmdHello, OK: true,
			Body: Welcome{Acks: []OutputAck{{TaskID: "t-run", StdoutOffset: 10, StderrOffset: 2}}},
		}, true
	case "request.ping":
		return fixtureFrame{
			Kind: FrameRequest, ID: 2, Name: CmdPing,
			Body: Ping{Seq: 42},
		}, true
	case "response.ping":
		return fixtureFrame{
			Kind: FrameResponse, ID: 2, Name: CmdPing, OK: true,
			Body: Ping{Seq: 42},
		}, true

	case "request.task.start.exec.argv":
		return fixtureFrame{
			Kind: FrameRequest, ID: 3, Name: CmdTaskStart,
			Body: TaskStart{
				TaskID:  "t-exec-argv",
				Attempt: 1,
				Spec: TaskSpec{Kind: TaskSpecExec, Exec: &ExecSpec{
					Command: Command{Kind: CommandArgv, Argv: []string{"/bin/echo", "hi"}},
					Env:     map[string]string{"A": "1", "B": "2"},
					Cwd:     "/tmp/数据",
					Stdin:   nil,
				}},
				Privileged:     false,
				Authorizations: [][]byte{{0x00, 0xff}},
				TimeoutMS:      30000,
				KillGraceMS:    5000,
				Output: OutputMode{
					Kind: OutputFull, SpillBytes: 1048576, SpillLines: 1000,
				},
			},
		}, true
	case "request.task.start.exec.shell":
		return fixtureFrame{
			Kind: FrameRequest, ID: 4, Name: CmdTaskStart,
			Body: TaskStart{
				TaskID:  "t-exec-shell",
				Attempt: 2,
				Spec: TaskSpec{Kind: TaskSpecExec, Exec: &ExecSpec{
					Command: Command{Kind: CommandShell, Shell: "echo 你好 | wc -c"},
					Env:     map[string]string{},
					Cwd:     "/tmp",
					Stdin:   &InputRef{Size: 3, SHA256: fixtureHash(0x11)},
				}},
				Privileged:     false,
				Authorizations: [][]byte{},
				TimeoutMS:      5000,
				KillGraceMS:    1000,
				Output:         OutputMode{Kind: OutputText},
			},
		}, true
	case "request.task.start.file.read":
		return fixtureFrame{
			Kind: FrameRequest, ID: 5, Name: CmdTaskStart,
			Body: TaskStart{
				TaskID:  "t-read",
				Attempt: 1,
				Spec: TaskSpec{Kind: TaskSpecFileRead, FileRead: &FileReadSpec{
					Path: "/etc/hosts", Offset: 0, Limit: 0,
				}},
				Authorizations: [][]byte{},
				Output:         OutputMode{Kind: OutputStatus},
			},
		}, true
	case "request.task.start.file.write":
		return fixtureFrame{
			Kind: FrameRequest, ID: 6, Name: CmdTaskStart,
			Body: TaskStart{
				TaskID:  "t-write",
				Attempt: 1,
				Spec: TaskSpec{Kind: TaskSpecFileWrite, FileWrite: &FileWriteSpec{
					Path:      "/tmp/x",
					Content:   InputRef{Size: 3, SHA256: fixtureHash(0x22)},
					Overwrite: false,
					Mode:      0,
					Owner:     "",
					Group:     "",
				}},
				Authorizations: [][]byte{},
				Output:         OutputMode{Kind: OutputStatus},
			},
		}, true
	case "request.task.start.file.edit":
		return fixtureFrame{
			Kind: FrameRequest, ID: 7, Name: CmdTaskStart,
			Body: TaskStart{
				TaskID:  "t-edit",
				Attempt: 1,
				Spec: TaskSpec{Kind: TaskSpecFileEdit, FileEdit: &FileEditSpec{
					Path: "/tmp/x",
					Edits: []Edit{
						{OldText: "a", NewText: "b"},
						{OldText: "你好", NewText: "世界"},
					},
				}},
				Authorizations: [][]byte{},
				Output:         OutputMode{Kind: OutputStatus},
			},
		}, true
	case "request.task.start.file.stat":
		return fixtureFrame{
			Kind: FrameRequest, ID: 8, Name: CmdTaskStart,
			Body: TaskStart{
				TaskID:         "t-stat",
				Attempt:        1,
				Spec:           TaskSpec{Kind: TaskSpecFileStat, FileStat: &FileStatSpec{Path: "/tmp/x"}},
				Authorizations: [][]byte{},
				Output:         OutputMode{Kind: OutputStatus},
			},
		}, true
	case "request.task.start.file.list":
		return fixtureFrame{
			Kind: FrameRequest, ID: 9, Name: CmdTaskStart,
			Body: TaskStart{
				TaskID:         "t-list",
				Attempt:        1,
				Spec:           TaskSpec{Kind: TaskSpecFileList, FileList: &FileListSpec{Path: "/tmp", Limit: 0}},
				Authorizations: [][]byte{},
				Output:         OutputMode{Kind: OutputStatus},
			},
		}, true
	case "response.task.start":
		return fixtureFrame{
			Kind: FrameResponse, ID: 3, Name: CmdTaskStart, OK: true,
			Body: Empty{},
		}, true
	case "request.task.input":
		return fixtureFrame{
			Kind: FrameRequest, ID: 10, Name: CmdTaskInput,
			Body: TaskInput{TaskID: "t-exec-shell", Offset: 0, Data: []byte{0x00, 0x01, 0x02, 0xff}},
		}, true
	case "response.task.input":
		return fixtureFrame{
			Kind: FrameResponse, ID: 10, Name: CmdTaskInput, OK: true,
			Body: Empty{},
		}, true
	case "request.task.cancel":
		return fixtureFrame{
			Kind: FrameRequest, ID: 11, Name: CmdTaskCancel,
			Body: TaskCancel{TaskID: "t-exec-argv"},
		}, true
	case "response.task.cancel":
		return fixtureFrame{
			Kind: FrameResponse, ID: 11, Name: CmdTaskCancel, OK: true,
			Body: Empty{},
		}, true
	case "request.task.query":
		return fixtureFrame{
			Kind: FrameRequest, ID: 12, Name: CmdTaskQuery,
			Body: TaskQuery{TaskID: "t-exec-argv"},
		}, true
	case "response.task.query":
		return fixtureFrame{
			Kind: FrameResponse, ID: 12, Name: CmdTaskQuery, OK: true,
			Body: TaskStatus{TaskID: "t-exec-argv", State: TaskExited, StdoutEnd: 6, StderrEnd: 0},
		}, true
	case "response.error":
		return fixtureFrame{
			Kind: FrameResponse, ID: 11, Name: CmdTaskCancel, OK: false,
			Err: &Error{Code: "internal_error", Message: "boom"},
		}, true

	case "event.task.output":
		return fixtureFrame{
			Kind: FrameEvent, Name: EventTaskOutput,
			Body: TaskOutput{TaskID: "t-exec-argv", Stream: StreamStdout, Offset: 0, Data: []byte("hello\n")},
		}, true
	case "event.task.exit.code":
		return fixtureFrame{
			Kind: FrameEvent, Name: EventTaskExit,
			Body: TaskExit{
				TaskID:     "t-exec-argv",
				Outcome:    Outcome{Kind: OutcomeCode, Code: 0},
				TimedOut:   false,
				Cancelled:  false,
				StdoutEnd:  6,
				StderrEnd:  0,
				OutputFile: "",
			},
		}, true
	case "event.task.exit.signal":
		return fixtureFrame{
			Kind: FrameEvent, Name: EventTaskExit,
			Body: TaskExit{
				TaskID:     "t-exec-shell",
				Outcome:    Outcome{Kind: OutcomeSignal, Signal: "TERM"},
				TimedOut:   false,
				Cancelled:  true,
				StdoutEnd:  3,
				StderrEnd:  0,
				OutputFile: "",
			},
		}, true
	case "event.task.exit.error":
		return fixtureFrame{
			Kind: FrameEvent, Name: EventTaskExit,
			Body: TaskExit{
				TaskID:     "t-edit",
				Outcome:    Outcome{Kind: OutcomeError, Error: &Error{Code: "internal_error", Message: "failed"}},
				TimedOut:   true,
				Cancelled:  false,
				StdoutEnd:  0,
				StderrEnd:  0,
				OutputFile: "/tmp/out",
			},
		}, true
	case "event.facts":
		return fixtureFrame{
			Kind: FrameEvent, Name: EventFacts,
			Body: fixtureFacts(),
		}, true
	case "event.node.status":
		return fixtureFrame{
			Kind: FrameEvent, Name: EventNodeStatus,
			Body: NodeStatus{NodeID: "node-1", State: NodeStatusActive, Message: "approved"},
		}, true
	case "event.task.output.ack":
		return fixtureFrame{
			Kind: FrameEvent, Name: EventOutputAck,
			Body: OutputAck{TaskID: "t-exec-argv", StdoutOffset: 6, StderrOffset: 0},
		}, true
	case "event.task.exit.ack":
		return fixtureFrame{
			Kind: FrameEvent, Name: EventTaskExitAck,
			Body: TaskExitAck{TaskID: "t-exec-argv"},
		}, true
	}
	return nil, false
}
